# Function to test MongoDB connection
function Test-MongoDBConnection {
    try {
        # Try to connect to MongoDB using mongosh
        $result = mongosh --eval "db.runCommand({ ping: 1 })" --quiet
        if ($result -match "ok") {
            return $true
        }
        return $false
    }
    catch {
        return $false
    }
}

# Function to create test database
function Initialize-TestDatabase {
    try {
        # Create test database and collection
        $initScript = @"
use healthcare-test
db.createCollection('users')
db.createCollection('patients')
db.createCollection('doctors')
db.createCollection('appointments')
"@
        $initScript | Out-File -FilePath "$env:TEMP\init-mongo.js" -Encoding UTF8
        mongosh --file "$env:TEMP\init-mongo.js" --quiet
        Remove-Item "$env:TEMP\init-mongo.js" -Force
        return $true
    }
    catch {
        Write-Host "Failed to initialize test database: $_"
        return $false
    }
}

Write-Host "Verifying MongoDB connection..."

if (-not (Test-MongoDBConnection)) {
    Write-Host "Failed to connect to MongoDB. Please ensure:"
    Write-Host "1. MongoDB service is running"
    Write-Host "2. MongoDB is installed correctly"
    Write-Host "3. No other process is using port 27017"
    exit 1
}

Write-Host "Successfully connected to MongoDB"

Write-Host "Initializing test database..."
if (-not (Initialize-TestDatabase)) {
    Write-Host "Failed to initialize test database"
    exit 1
}

Write-Host "Test database initialized successfully"
Write-Host "You can now run the tests using: npm run test:run" 